function renderPreview(){let h='<section class="reviewIntro"><span>お客様にご確認いただく画面です</span><b>お名前・ご住所・明細・金額をご確認ください</b></section><section class="reviewCustomer"><div class="reviewSectionTitle"><span>1</span><div><small>お客様情報</small><h2>'+K.esc(draft.customer.name||"お客様")+' 様</h2></div></div><dl><div><dt>郵便番号</dt><dd>'+K.esc(draft.customer.postalCode?"〒"+draft.customer.postalCode:"未登録")+'</dd></div><div><dt>ご住所</dt><dd>'+K.esc(draft.customer.address||"未登録")+'</dd></div><div><dt>電話番号</dt><dd>'+K.esc(draft.customer.phone||"未登録")+'</dd></div></dl></section><section class="reviewDetails"><div class="reviewSectionTitle"><span>2</span><div><small>商品・作業</small><h2>明細と金額</h2></div></div>';let sectionCount=0;for(const key of draft.selected){if(!draft.items[key].length)continue;sectionCount++;h+='<div class="reviewService"><h3>'+services[key]+'</h3>'+draft.items[key].map((x,index)=>'<div class="reviewLine"><div><small>'+(index+1)+'</small><span>'+K.esc([x.category,x.maker,x.model,x.year||"年式不明",x.spec].filter(Boolean).join(" / "))+'</span>'+(x.sourceForm?'<em>'+(x.sourceFormEditedAt?'案内フォーム反映・現場編集済み':'案内フォーム反映')+'</em>':'')+'</div><b>¥'+Number(x.amount||0).toLocaleString()+'</b></div>').join("")+'</div>'}if(!sectionCount)h+='<div class="reviewEmpty">明細はありません</div>';const signedTotal=draftTotal(),customerReceives=signedTotal<0,totalLabel=customerReceives?"お客様受取額":"お客様ご確認金額",totalNote=customerReceives?"当店からお客様へお支払いする買取金額です":"この明細のご確認金額です";h+='</section><section class="reviewGrandTotal"><span>'+totalLabel+'</span><b>¥'+Math.abs(signedTotal).toLocaleString()+'</b><small>'+totalNote+'</small></section>';K.$("#previewBody").innerHTML=h}
let sig={canvas:null,ctx:null,drawn:false,drawing:false,last:null};

function setupSignature(){const canvas=K.$("#signatureCanvas");if(!canvas)return;const rect=canvas.getBoundingClientRect(),dpr=Math.max(1,window.devicePixelRatio||1);canvas.width=Math.max(1,Math.floor(rect.width*dpr));canvas.height=Math.max(1,Math.floor(150*dpr));const ctx=canvas.getContext("2d");ctx.scale(dpr,dpr);ctx.lineWidth=2;ctx.lineCap="round";ctx.lineJoin="round";ctx.strokeStyle="#24332e";sig={canvas,ctx,drawn:false,drawing:false,last:null};const point=e=>{const r=canvas.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top}};canvas.onpointerdown=e=>{e.preventDefault();canvas.setPointerCapture?.(e.pointerId);sig.drawing=true;sig.last=point(e)};canvas.onpointermove=e=>{if(!sig.drawing)return;e.preventDefault();const p=point(e);ctx.beginPath();ctx.moveTo(sig.last.x,sig.last.y);ctx.lineTo(p.x,p.y);ctx.stroke();sig.last=p;sig.drawn=true};const end=e=>{if(!sig.drawing)return;e.preventDefault();sig.drawing=false;sig.last=null};canvas.onpointerup=end;canvas.onpointercancel=end;canvas.onpointerleave=end}

function clearSignature(){if(!sig.ctx||!sig.canvas)return;sig.ctx.clearRect(0,0,sig.canvas.width,sig.canvas.height);sig.drawn=false}
async function sha256(text){const b=await crypto.subtle.digest("SHA-256",new TextEncoder().encode(text));return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,"0")).join("")}
function setDeliveryLabel(button,label){const text=button?.querySelector("span:last-child");if(text)text.textContent=label;else if(button)button.textContent=label}
async function finalizeSnapshot(){
  if(!draft)return;
  if(stopForDraftIssues())return;
  if(!K.$("#confirmCustomerDetails").checked||!K.$("#confirmPurchaseTerms").checked){
    alert("2つの確認項目にチェックしてください。");
    return;
  }
  if(draft.selected.includes("purchase")&&!sig.drawn){
    alert("買取を含むため、お客様サインを入力してください。");
    return;
  }
  await save();
  const previous=await KRDB.snapshotsFor(draft.id),version=(previous.at(-1)?.version||0)+1,confirmedAt=new Date().toISOString();
  const payload=JSON.parse(JSON.stringify(draft));
  payload.confirmations={customerDetails:true,purchaseTerms:true};
  const signatureDataUrl=sig.drawn?sig.canvas.toDataURL("image/png"):"";
  const hash=await sha256(JSON.stringify({payload,confirmedAt,version}));
  const snap={id:"snapshot-"+draft.id+"-v"+version,draftId:draft.id,caseId:draft.caseId||"",sourceServiceOrderId:draft.sourceServiceOrderId||"",version,confirmedAt,total:draftTotal(),payload,signatureDataUrl,hash,status:"local-confirmed"};
  await KRDB.putSnapshot(snap);
  let syncState=null;
  if(window.KRAPI)syncState=await KRAPI.run("finalize-slip",snap.id,snap);
  else await KRDB.enqueue({id:"sync-"+snap.id,operation:"finalize-slip",entityId:snap.id,payload:snap,status:"pending",attempts:0,createdAt:confirmedAt});
  await KRDB.deleteDraft(draft.id);

  const apiResult=syncState&&!syncState.queued?(syncState.result?.result||syncState.result||{}):null;
  const serviceOrderId=apiResult?.serviceOrderId||draft.sourceServiceOrderId||"";
  const blueSend=K.$("#bluePdfSend");
  blueSend.dataset.slip=serviceOrderId;
  blueSend.dataset.version=String(version);
  blueSend.dataset.email=String(draft.customer.email||"").trim();
  blueSend.dataset.phone=String(draft.customer.phone||"").trim();
  blueSend.dataset.pdf=String(apiResult?.pdfFileUrl||"");
  blueSend.dataset.resend="0";
  const canEmail=Boolean(apiResult&&serviceOrderId&&blueSend.dataset.email);
  blueSend.dataset.mode=canEmail?"email":"blue";
  blueSend.disabled=!serviceOrderId;
  setDeliveryLabel(blueSend,canEmail?"メール送信":(serviceOrderId?"メール未登録":"確定後に送信"));
  const sms=K.$("#smsPdfShare"),line=K.$("#linePdfShare");
  [sms,line].forEach(button=>{button.disabled=!serviceOrderId;button.dataset.slip=serviceOrderId;button.dataset.version=String(version);button.dataset.phone=String(draft.customer.phone||"").trim();button.dataset.pdf=String(apiResult?.pdfFileUrl||"")});

  const hasPurchase=draft.selected.includes("purchase");
  if(draft.caseId&&K.updateLocalCase){
    await K.updateLocalCase(draft.caseId,{status:hasPurchase?"買取確定":"伝票確定",nextAction:hasPurchase?"在庫工程へ":"完了確認",updatedAt:confirmedAt});
  }
  if(draft.appointmentId){
    const appts=await KRDB.listAppointments().catch(()=>[]),a=appts.find(x=>String(x.appointmentId)===String(draft.appointmentId));
    if(a){
      a.status="completed";
      a.updatedAt=confirmedAt;
      if(serviceOrderId)a.serviceOrderId=serviceOrderId;
      await KRDB.putAppointment(a);
    }
  }
  K.renderCalendar&&K.renderCalendar();
  K.renderHome&&K.renderHome();
  K.$("#confirmedPanel").classList.remove("hidden");
  const generated=Array.isArray(apiResult?.inventory)?apiResult.inventory:[];
  const pdfUrl=String(apiResult?.pdfFileUrl||"");
  let statusHtml="<b>✓ お客様確認済み・第"+version+"版</b><span>"+new Date(confirmedAt).toLocaleString("ja-JP")+(apiResult?" / Green保存済み":" / Green共有同期待ち")+"</span>";
  statusHtml+='<div class="documentDeliveryStatus"><div><span>PDF</span><b>'+(apiResult?("第"+version+"版 発行済み"):"同期後に発行")+'</b></div><div><span>顧客送信</span><b class="unsent">未送信</b></div></div><div id="documentSendResult" class="documentSendResult" role="status"></div>';
  if(pdfUrl)statusHtml+='<a class="confirmedPdfLink" target="_blank" rel="noopener" href="'+K.esc(pdfUrl)+'">発行PDFを確認</a>';
  if(generated.length)statusHtml+='<div class="generatedInventoryLinks"><small>在庫を自動生成しました</small>'+generated.map((x,i)=>'<button type="button" data-inv="'+K.esc(x.inventoryId||"")+'" data-no="'+K.esc(x.inventoryNo||"")+'">'+K.esc(x.inventoryNo||("在庫"+(i+1)))+' を開く</button>').join("")+'</div>';
  K.$("#confirmedPanel").innerHTML=statusHtml;
  setupDocumentChoices(apiResult?.pdfs || [], serviceOrderId);
  if(apiResult && serviceOrderId) prepareIssuedPdf(serviceOrderId).catch(()=>{});
  K.$$("#confirmedPanel .generatedInventoryLinks button").forEach(b=>b.onclick=async()=>{
    const id=b.dataset.inv,no=b.dataset.no;
    try{
      const live=await KRAPI.getSnapshot();
      if(live&&Array.isArray(live.inventory)){
        K.snap=live;
        const item=live.inventory.find(x=>x.inventoryId===id||x.inventoryNo===no);
        if(item){
          K.overlay("preview").classList.remove("on");
          K.overlay("slip").classList.remove("on");
          K.openInventoryDetail&&K.openInventoryDetail(item);
          return;
        }
      }
    }catch{}
    const u=new URL(location.href);
    u.searchParams.set("inventory",id||no);
    location.href=u.toString();
  });
  K.$("#previewStatus").textContent="第"+version+"版・端末確定済み";
  K.$("#finalizeConfirmation").disabled=true;
  K.$("#finalizeConfirmation").textContent="✓ 確定済み";
  await K.refreshResume();
}
function closePreviewSafely(){K.overlay("preview").classList.remove("on");K.overlay("slip").classList.add("on")}
